insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Heart', 'The heart is a muscular organ found in humans and other animals. This organ pumps blood through the blood vessels. The heart and blood vessels together make up the circulatory system. The pumped blood carries oxygen and nutrients to the tissue, while carrying metabolic waste such as carbon dioxide to the lungs. In humans, the heart is approximately the size of a closed fist and is located between the lungs, in the middle compartment of the chest, called the mediastinum. In humans, the heart is divided into four chambers: upper left and right atria and lower left and right ventricles. Commonly, the right atrium and ventricle are referred together as the right heart and their left counterparts as the left heart. In a healthy heart, blood flows one way through the heart due to heart valves, which prevent backflow. The heart is enclosed in a protective sac, the pericardium, which also contains a small amount of fluid. The wall of the heart is made up of three layers: epicardium, myocardium, and endocardium.', 'Wikipedia: Heart', 'https://en.wikipedia.org/w/index.php?title=Heart&oldid=1378398002', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The heart is a muscular organ found in humans and other animals. This organ pumps blood through the blood vessels. The heart and blood vessels together make up the circulatory system. The pumped blood carries oxygen and nutrients to the tissue, while carrying metabolic waste such as carbon dioxide to the lungs. In humans, the heart is approximately the size of a closed fist and is located between the lungs, in the middle compartment of the chest, called the mediastinum. In humans, the heart is divided into four chambers: upper left and right atria and lower left and right ventricles. Commonly, the right atrium and ventricle are referred together as the right heart and their left counterparts as the left heart. In a healthy heart, blood flows one way through the heart due to heart valves, which prevent backflow. The heart is enclosed in a protective sac, the pericardium, which also contains a small amount of fluid. The wall of the heart is made up of three layers: epicardium, myocardium, and endocardium.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Heart', 'The heart pumps blood with a rhythm determined by a group of pacemaker cells in the sinoatrial node. These generate an electric current that causes the heart to contract, traveling through the atrioventricular node and along the conduction system of the heart. In humans, deoxygenated blood enters the heart through the right atrium from the superior and inferior venae cavae and passes to the right ventricle. From here, it is pumped into pulmonary circulation to the lungs, where it receives oxygen and gives off carbon dioxide. Oxygenated blood then returns to the left atrium, passes through the left ventricle and is pumped out through the aorta into systemic circulation, traveling through arteries, arterioles, and capillaries—where nutrients and other substances are exchanged between blood vessels and cells, losing oxygen and gaining carbon dioxide—before being returned to the heart through venules and veins. The adult heart beats at a resting rate close to 72 beats per minute.', 'Wikipedia: Heart', 'https://en.wikipedia.org/w/index.php?title=Heart&oldid=1378398002', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The heart pumps blood with a rhythm determined by a group of pacemaker cells in the sinoatrial node. These generate an electric current that causes the heart to contract, traveling through the atrioventricular node and along the conduction system of the heart. In humans, deoxygenated blood enters the heart through the right atrium from the superior and inferior venae cavae and passes to the right ventricle. From here, it is pumped into pulmonary circulation to the lungs, where it receives oxygen and gives off carbon dioxide. Oxygenated blood then returns to the left atrium, passes through the left ventricle and is pumped out through the aorta into systemic circulation, traveling through arteries, arterioles, and capillaries—where nutrients and other substances are exchanged between blood vessels and cells, losing oxygen and gaining carbon dioxide—before being returned to the heart through venules and veins. The adult heart beats at a resting rate close to 72 beats per minute.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Heart', 'Cardiovascular diseases are the most common cause of death globally; an estimated 19.8 million people died from them in 2022, representing about 32% of all deaths worldwide. Of these, 85% were due to heart attack and stroke. Risk factors include: smoking, being overweight, little exercise, high cholesterol, high blood pressure, and poorly controlled diabetes, among others. Cardiovascular diseases do not frequently have symptoms but may cause chest pain or shortness of breath. Diagnosis of heart disease is often done by the taking of a medical history, listening to the heart-sounds with a stethoscope, as well as with ECG, and echocardiogram which uses ultrasound. Specialists who focus on diseases of the heart are called cardiologists, although many specialties of medicine may be involved in treatment.', 'Wikipedia: Heart', 'https://en.wikipedia.org/w/index.php?title=Heart&oldid=1378398002', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Cardiovascular diseases are the most common cause of death globally; an estimated 19.8 million people died from them in 2022, representing about 32% of all deaths worldwide. Of these, 85% were due to heart attack and stroke. Risk factors include: smoking, being overweight, little exercise, high cholesterol, high blood pressure, and poorly controlled diabetes, among others. Cardiovascular diseases do not frequently have symptoms but may cause chest pain or shortness of breath. Diagnosis of heart disease is often done by the taking of a medical history, listening to the heart-sounds with a stethoscope, as well as with ECG, and echocardiogram which uses ultrasound. Specialists who focus on diseases of the heart are called cardiologists, although many specialties of medicine may be involved in treatment.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Heart: Location and shape', 'The human heart is situated in the mediastinum, at the level of thoracic vertebrae T5–T8. A double-membraned sac called the pericardium surrounds the heart and attaches to the mediastinum. The back surface of the heart lies near the vertebral column, and the front surface, known as the sternocostal surface, sits behind the sternum and rib cartilages. The upper part of the heart is the attachment point for several large blood vessels—the venae cavae, aorta and pulmonary trunk. The upper part of the heart is located at the level of the third costal cartilage. The lower tip of the heart, the apex, lies to the left of the sternum (8 to 9 cm from the midsternal line) between the junction of the fourth and fifth ribs near their articulation with the costal cartilages. The largest part of the heart is usually slightly offset to the left side of the chest (levocardia). In a rare congenital disorder (dextrocardia) the heart is offset to the right side and is felt to be on the left because the left heart is stronger and larger, since it pumps to all body parts. Because the heart is between the lungs, the left lung is smaller than the right lung and has a cardiac notch in its border to accommodate the heart.', 'Wikipedia: Heart', 'https://en.wikipedia.org/w/index.php?title=Heart&oldid=1378398002', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The human heart is situated in the mediastinum, at the level of thoracic vertebrae T5–T8. A double-membraned sac called the pericardium surrounds the heart and attaches to the mediastinum. The back surface of the heart lies near the vertebral column, and the front surface, known as the sternocostal surface, sits behind the sternum and rib cartilages. The upper part of the heart is the attachment point for several large blood vessels—the venae cavae, aorta and pulmonary trunk. The upper part of the heart is located at the level of the third costal cartilage. The lower tip of the heart, the apex, lies to the left of the sternum (8 to 9 cm from the midsternal line) between the junction of the fourth and fifth ribs near their articulation with the costal cartilages. The largest part of the heart is usually slightly offset to the left side of the chest (levocardia). In a rare congenital disorder (dextrocardia) the heart is offset to the right side and is felt to be on the left because the left heart is stronger and larger, since it pumps to all body parts. Because the heart is between the lungs, the left lung is smaller than the right lung and has a cardiac notch in its border to accommodate the heart.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Heart: Location and shape', 'The heart is cone-shaped, with its base positioned upwards and tapering down to the apex. An adult heart has a mass of 250–350 grams (9–12 oz). The heart is often described as the size of a fist: 12 cm (5 in) in length, 8 cm (3.5 in) wide, and 6 cm (2.5 in) in thickness, although this description is disputed, as the heart is likely to be slightly larger. Well-trained athletes can have much larger hearts due to the effects of exercise on the heart muscle, similar to the response of skeletal muscle.', 'Wikipedia: Heart', 'https://en.wikipedia.org/w/index.php?title=Heart&oldid=1378398002', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The heart is cone-shaped, with its base positioned upwards and tapering down to the apex. An adult heart has a mass of 250–350 grams (9–12 oz). The heart is often described as the size of a fist: 12 cm (5 in) in length, 8 cm (3.5 in) wide, and 6 cm (2.5 in) in thickness, although this description is disputed, as the heart is likely to be slightly larger. Well-trained athletes can have much larger hearts due to the effects of exercise on the heart muscle, similar to the response of skeletal muscle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Heart: Chambers', 'The heart has four chambers, two upper atria, the receiving chambers, and two lower ventricles, the discharging chambers. The atria open into the ventricles via the atrioventricular valves, present in the atrioventricular septum. This distinction is visible also on the surface of the heart as the coronary sulcus. There is an ear-shaped structure in the upper right atrium called the right atrial appendage, or auricle, and another in the upper left atrium, the left atrial appendage. The right atrium and the right ventricle together are sometimes referred to as the right heart. Similarly, the left atrium and the left ventricle together are sometimes referred to as the left heart. The ventricles are separated from each other by the interventricular septum, visible on the surface of the heart as the anterior longitudinal sulcus and the posterior interventricular sulcus.', 'Wikipedia: Heart', 'https://en.wikipedia.org/w/index.php?title=Heart&oldid=1378398002', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The heart has four chambers, two upper atria, the receiving chambers, and two lower ventricles, the discharging chambers. The atria open into the ventricles via the atrioventricular valves, present in the atrioventricular septum. This distinction is visible also on the surface of the heart as the coronary sulcus. There is an ear-shaped structure in the upper right atrium called the right atrial appendage, or auricle, and another in the upper left atrium, the left atrial appendage. The right atrium and the right ventricle together are sometimes referred to as the right heart. Similarly, the left atrium and the left ventricle together are sometimes referred to as the left heart. The ventricles are separated from each other by the interventricular septum, visible on the surface of the heart as the anterior longitudinal sulcus and the posterior interventricular sulcus.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Heart: Chambers', 'The fibrous cardiac skeleton gives structure to the heart. It forms the atrioventricular septum, which separates the atria from the ventricles, and the fibrous rings, which serve as bases for the four heart valves. The cardiac skeleton also provides an important boundary in the heart''s electrical conduction system since collagen cannot conduct electricity. The interatrial septum separates the atria, and the interventricular septum separates the ventricles. The interventricular septum is much thicker than the interatrial septum since the ventricles need to generate greater pressure when they contract.', 'Wikipedia: Heart', 'https://en.wikipedia.org/w/index.php?title=Heart&oldid=1378398002', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The fibrous cardiac skeleton gives structure to the heart. It forms the atrioventricular septum, which separates the atria from the ventricles, and the fibrous rings, which serve as bases for the four heart valves. The cardiac skeleton also provides an important boundary in the heart''s electrical conduction system since collagen cannot conduct electricity. The interatrial septum separates the atria, and the interventricular septum separates the ventricles. The interventricular septum is much thicker than the interatrial septum since the ventricles need to generate greater pressure when they contract.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Heart: Valves', 'The heart has four valves, which separate its chambers. One valve lies between each atrium and ventricle, and one valve rests at the exit of each ventricle. The valves between the atria and ventricles are called the atrioventricular valves. Between the right atrium and the right ventricle is the tricuspid valve. The tricuspid valve has three cusps, which connect to chordae tendinae and three papillary muscles named the anterior, posterior, and septal muscles, after their relative positions. The mitral valve lies between the left atrium and left ventricle. It is also known as the bicuspid valve due to its having two cusps, an anterior and a posterior cusp. These cusps are also attached via chordae tendinae to two papillary muscles projecting from the ventricular wall. The papillary muscles extend from the walls of the heart to valves by cartilaginous connections called chordae tendinae. These muscles prevent the valves from falling too far back when they close. During the relaxation phase of the cardiac cycle, the papillary muscles are also relaxed and the tension on the chordae tendineae is slight. As the heart chambers contract, so do the papillary muscles. This creates tension on the chordae tendineae, helping to hold the cusps of the atrioventricular valves in place and preventing them from being blown back into the atria.', 'Wikipedia: Heart', 'https://en.wikipedia.org/w/index.php?title=Heart&oldid=1378398002', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The heart has four valves, which separate its chambers. One valve lies between each atrium and ventricle, and one valve rests at the exit of each ventricle. The valves between the atria and ventricles are called the atrioventricular valves. Between the right atrium and the right ventricle is the tricuspid valve. The tricuspid valve has three cusps, which connect to chordae tendinae and three papillary muscles named the anterior, posterior, and septal muscles, after their relative positions. The mitral valve lies between the left atrium and left ventricle. It is also known as the bicuspid valve due to its having two cusps, an anterior and a posterior cusp. These cusps are also attached via chordae tendinae to two papillary muscles projecting from the ventricular wall. The papillary muscles extend from the walls of the heart to valves by cartilaginous connections called chordae tendinae. These muscles prevent the valves from falling too far back when they close. During the relaxation phase of the cardiac cycle, the papillary muscles are also relaxed and the tension on the chordae tendineae is slight. As the heart chambers contract, so do the papillary muscles. This creates tension on the chordae tendineae, helping to hold the cusps of the atrioventricular valves in place and preventing them from being blown back into the atria.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac cycle', 'The cardiac cycle is the performance of the human heart from the beginning of one heartbeat to the beginning of the next. It consists of two periods: one during which the heart muscle relaxes and refills with blood, called diastole, following a period of robust contraction and pumping of blood, called systole. After emptying, the heart relaxes and expands to receive another influx of blood returning from the lungs and other systems of the body, before again contracting. Assuming a healthy heart and a typical rate of 70 to 75 beats per minute, each cardiac cycle, or heartbeat, takes about 0.8 second to complete the cycle. Duration of the cardiac cycle is inversely proportional to the heart rate.', 'Wikipedia: Cardiac cycle', 'https://en.wikipedia.org/w/index.php?title=Cardiac_cycle&oldid=1376968670', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The cardiac cycle is the performance of the human heart from the beginning of one heartbeat to the beginning of the next. It consists of two periods: one during which the heart muscle relaxes and refills with blood, called diastole, following a period of robust contraction and pumping of blood, called systole. After emptying, the heart relaxes and expands to receive another influx of blood returning from the lungs and other systems of the body, before again contracting. Assuming a healthy heart and a typical rate of 70 to 75 beats per minute, each cardiac cycle, or heartbeat, takes about 0.8 second to complete the cycle. Duration of the cardiac cycle is inversely proportional to the heart rate.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac cycle: Description', 'There are two atrial and two ventricle chambers of the heart; they are paired as the left heart and the right heart—that is, the left atrium with the left ventricle, the right atrium with the right ventricle—and they work in concert to repeat the cardiac cycle continuously (see cycle diagram at right margin). At the start of the cycle, during ventricular diastole–early, the heart relaxes and expands while receiving blood into both ventricles through both atria; then, near the end of ventricular diastole–late, the two atria begin to contract (atrial systole), and each atrium pumps blood into the ventricle below it. During ventricular systole the ventricles contract and vigorously pulse (or eject) two separated blood supplies from the heart—one to the lungs and one to all other body organs and systems—while the two atria relax (atrial diastole). This precise coordination ensures that blood is efficiently collected and circulated throughout the body.', 'Wikipedia: Cardiac cycle', 'https://en.wikipedia.org/w/index.php?title=Cardiac_cycle&oldid=1376968670', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'There are two atrial and two ventricle chambers of the heart; they are paired as the left heart and the right heart—that is, the left atrium with the left ventricle, the right atrium with the right ventricle—and they work in concert to repeat the cardiac cycle continuously (see cycle diagram at right margin). At the start of the cycle, during ventricular diastole–early, the heart relaxes and expands while receiving blood into both ventricles through both atria; then, near the end of ventricular diastole–late, the two atria begin to contract (atrial systole), and each atrium pumps blood into the ventricle below it. During ventricular systole the ventricles contract and vigorously pulse (or eject) two separated blood supplies from the heart—one to the lungs and one to all other body organs and systems—while the two atria relax (atrial diastole). This precise coordination ensures that blood is efficiently collected and circulated throughout the body.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac cycle: Description', 'The mitral and tricuspid valves, also known as the atrioventricular, or AV valves, open during ventricular diastole to permit filling. Late in the filling period the atria begin to contract (atrial systole) forcing a final crop of blood into the ventricles under pressure—see cycle diagram. Then, prompted by electrical signals from the sinoatrial node, the ventricles start contracting (ventricular systole), and as back-pressure against them increases the AV valves are forced to close, which stops the blood volumes in the ventricles from flowing in or out; this is known as the isovolumic contraction stage. Due to the contractions of the systole, pressures in the ventricles rise quickly, exceeding the pressures in the trunks of the aorta and the pulmonary arteries and causing the requisite valves (the aortic and pulmonary valves) to open—which results in separated blood volumes being ejected from the two ventricles. This is the ejection stage of the cardiac cycle; it is depicted (see circular diagram) as the ventricular systole–first phase followed by the ventricular systole–second phase. After ventricular pressures fall below their peak(s) and below those in the trunks of the aorta and pulmonary arteries, the aortic and pulmonary valves close again—see, at the right margin, Wiggers diagram, blue-line tracing.', 'Wikipedia: Cardiac cycle', 'https://en.wikipedia.org/w/index.php?title=Cardiac_cycle&oldid=1376968670', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The mitral and tricuspid valves, also known as the atrioventricular, or AV valves, open during ventricular diastole to permit filling. Late in the filling period the atria begin to contract (atrial systole) forcing a final crop of blood into the ventricles under pressure—see cycle diagram. Then, prompted by electrical signals from the sinoatrial node, the ventricles start contracting (ventricular systole), and as back-pressure against them increases the AV valves are forced to close, which stops the blood volumes in the ventricles from flowing in or out; this is known as the isovolumic contraction stage. Due to the contractions of the systole, pressures in the ventricles rise quickly, exceeding the pressures in the trunks of the aorta and the pulmonary arteries and causing the requisite valves (the aortic and pulmonary valves) to open—which results in separated blood volumes being ejected from the two ventricles. This is the ejection stage of the cardiac cycle; it is depicted (see circular diagram) as the ventricular systole–first phase followed by the ventricular systole–second phase. After ventricular pressures fall below their peak(s) and below those in the trunks of the aorta and pulmonary arteries, the aortic and pulmonary valves close again—see, at the right margin, Wiggers diagram, blue-line tracing.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac cycle: Description', 'Next is the isovolumic relaxation, during which pressure within the ventricles begin to fall significantly, and thereafter the atria begin refilling as blood returns to flow into the right atrium (from the vena cavae) and into the left atrium (from the pulmonary veins). As the ventricles begin to relax, the mitral and tricuspid valves open again, and the completed cycle returns to ventricular diastole and a new "Start" of the cardiac cycle. Throughout the cardiac cycle, blood pressure increases and decreases. The movements of cardiac muscle are coordinated by a series of electrical impulses produced by specialized pacemaker cells found within the sinoatrial node and the atrioventricular node. Cardiac muscle is composed of myocytes which initiate their internal contractions without receiving signals from external nerves—with the exception of changes in the heart rate due to metabolic demand. In an electrocardiogram, electrical systole initiates the atrial systole at the P wave deflection of a steady signal; and it starts contractions (systole).', 'Wikipedia: Cardiac cycle', 'https://en.wikipedia.org/w/index.php?title=Cardiac_cycle&oldid=1376968670', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Next is the isovolumic relaxation, during which pressure within the ventricles begin to fall significantly, and thereafter the atria begin refilling as blood returns to flow into the right atrium (from the vena cavae) and into the left atrium (from the pulmonary veins). As the ventricles begin to relax, the mitral and tricuspid valves open again, and the completed cycle returns to ventricular diastole and a new "Start" of the cardiac cycle. Throughout the cardiac cycle, blood pressure increases and decreases. The movements of cardiac muscle are coordinated by a series of electrical impulses produced by specialized pacemaker cells found within the sinoatrial node and the atrioventricular node. Cardiac muscle is composed of myocytes which initiate their internal contractions without receiving signals from external nerves—with the exception of changes in the heart rate due to metabolic demand. In an electrocardiogram, electrical systole initiates the atrial systole at the P wave deflection of a steady signal; and it starts contractions (systole).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac cycle: Cardiac cycle and Wiggers diagram', 'The cardiac cycle involves four major stages of activity: 1) "isovolumic relaxation", 2) inflow, 3) "isovolumic contraction", 4) "ejection". Stages 1 and 2 together—"isovolumic relaxation" plus inflow (equals "rapid inflow", "diastasis", and "atrial systole")—comprise the ventricular diastole period, including atrial systole, during which blood returning to the heart flows through the atria into the relaxed ventricles. Stages 3 and 4 together—"isovolumic contraction" plus "ejection"—are the ventricular systole period, which is the simultaneous pumping of separate blood supplies from the two ventricles, one to the pulmonary artery and one to the aorta. Notably, near the end of the diastole, the atria begin contracting, then pump blood into the ventricles; this pressurized delivery during ventricular relaxation (ventricular diastole) is called the atrial systole. The closure of the aortic valve causes a rapid change in pressure in the aorta called the incisura. This short sharp change in pressure is rapidly attenuated down the arterial tree. The pulse wave form is also reflected from branches in the arterial tree and gives rise to a dicrotic notch in main arteries. The summation of the reflected pulse wave and the systolic wave may increase pulse pressure and help tissue perfusion. With increasing age, the aorta stiffens and can become less elastic which will reduce peak pulse in the periphery.', 'Wikipedia: Cardiac cycle', 'https://en.wikipedia.org/w/index.php?title=Cardiac_cycle&oldid=1376968670', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The cardiac cycle involves four major stages of activity: 1) "isovolumic relaxation", 2) inflow, 3) "isovolumic contraction", 4) "ejection". Stages 1 and 2 together—"isovolumic relaxation" plus inflow (equals "rapid inflow", "diastasis", and "atrial systole")—comprise the ventricular diastole period, including atrial systole, during which blood returning to the heart flows through the atria into the relaxed ventricles. Stages 3 and 4 together—"isovolumic contraction" plus "ejection"—are the ventricular systole period, which is the simultaneous pumping of separate blood supplies from the two ventricles, one to the pulmonary artery and one to the aorta. Notably, near the end of the diastole, the atria begin contracting, then pump blood into the ventricles; this pressurized delivery during ventricular relaxation (ventricular diastole) is called the atrial systole. The closure of the aortic valve causes a rapid change in pressure in the aorta called the incisura. This short sharp change in pressure is rapidly attenuated down the arterial tree. The pulse wave form is also reflected from branches in the arterial tree and gives rise to a dicrotic notch in main arteries. The summation of the reflected pulse wave and the systolic wave may increase pulse pressure and help tissue perfusion. With increasing age, the aorta stiffens and can become less elastic which will reduce peak pulse in the periphery.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac cycle: Physiology', 'The heart is a four-chambered organ consisting of right and left halves, called the right heart and the left heart. The upper two chambers, the left and right atria, are entry points into the heart for blood-flow returning from the circulatory system, while the two lower chambers, the left and right ventricles, perform the contractions that eject the blood from the heart to flow through the circulatory system. Circulation is split into pulmonary circulation—during which the right ventricle pumps oxygen-depleted blood to the lungs through the pulmonary trunk and arteries; or the systemic circulation—in which the left ventricle pumps/ejects newly oxygenated blood throughout the body via the aorta and all other arteries.', 'Wikipedia: Cardiac cycle', 'https://en.wikipedia.org/w/index.php?title=Cardiac_cycle&oldid=1376968670', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The heart is a four-chambered organ consisting of right and left halves, called the right heart and the left heart. The upper two chambers, the left and right atria, are entry points into the heart for blood-flow returning from the circulatory system, while the two lower chambers, the left and right ventricles, perform the contractions that eject the blood from the heart to flow through the circulatory system. Circulation is split into pulmonary circulation—during which the right ventricle pumps oxygen-depleted blood to the lungs through the pulmonary trunk and arteries; or the systemic circulation—in which the left ventricle pumps/ejects newly oxygenated blood throughout the body via the aorta and all other arteries.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac cycle: Heart electrical conduction system', 'In a healthy heart all activities and rests during each individual cardiac cycle, or heartbeat, are initiated and orchestrated by signals of the heart''s electrical conduction system, which is the "wiring" of the heart that carries electrical impulses throughout the body of cardiomyocytes, the specialized muscle cells of the heart. These impulses ultimately stimulate heart muscle to contract and thereby to eject blood from the ventricles into the arteries and the cardiac circulatory system; and they provide a system of intricately timed and persistent signaling that controls the rhythmic beating of the heart muscle cells, especially the complex impulse-generation and muscle contractions in the atrial chambers. The rhythmic sequence (or sinus rhythm) of this signaling across the heart is coordinated by two groups of specialized cells, the sinoatrial (SA) node, which is situated in the upper wall of the right atrium, and the atrioventricular (AV) node located in the lower wall of the right heart between the atrium and ventricle. The sinoatrial node, often known as the cardiac pacemaker, is the point of origin for producing a wave of electrical impulses that stimulates atrial contraction by creating an action potential across myocardium cells.', 'Wikipedia: Cardiac cycle', 'https://en.wikipedia.org/w/index.php?title=Cardiac_cycle&oldid=1376968670', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'In a healthy heart all activities and rests during each individual cardiac cycle, or heartbeat, are initiated and orchestrated by signals of the heart''s electrical conduction system, which is the "wiring" of the heart that carries electrical impulses throughout the body of cardiomyocytes, the specialized muscle cells of the heart. These impulses ultimately stimulate heart muscle to contract and thereby to eject blood from the ventricles into the arteries and the cardiac circulatory system; and they provide a system of intricately timed and persistent signaling that controls the rhythmic beating of the heart muscle cells, especially the complex impulse-generation and muscle contractions in the atrial chambers. The rhythmic sequence (or sinus rhythm) of this signaling across the heart is coordinated by two groups of specialized cells, the sinoatrial (SA) node, which is situated in the upper wall of the right atrium, and the atrioventricular (AV) node located in the lower wall of the right heart between the atrium and ventricle. The sinoatrial node, often known as the cardiac pacemaker, is the point of origin for producing a wave of electrical impulses that stimulates atrial contraction by creating an action potential across myocardium cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac cycle: Heart electrical conduction system', 'Impulses of the wave are delayed upon reaching the AV node, which acts as a gate to slow and to coordinate the electrical current before it is conducted below the atria and through the circuits known as the bundle of His and the Purkinje fibers—all which stimulate contractions of both ventricles. The programmed delay at the AV node also provides time for blood volume to flow through the atria and fill the ventricular chambers—just before the return of the systole (contractions), ejecting the new blood volume and completing the cardiac cycle. (See Wiggers diagram: "Ventricular volume" tracing (red), at "Systole" panel.)', 'Wikipedia: Cardiac cycle', 'https://en.wikipedia.org/w/index.php?title=Cardiac_cycle&oldid=1376968670', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Impulses of the wave are delayed upon reaching the AV node, which acts as a gate to slow and to coordinate the electrical current before it is conducted below the atria and through the circuits known as the bundle of His and the Purkinje fibers—all which stimulate contractions of both ventricles. The programmed delay at the AV node also provides time for blood volume to flow through the atria and fill the ventricular chambers—just before the return of the systole (contractions), ejecting the new blood volume and completing the cardiac cycle. (See Wiggers diagram: "Ventricular volume" tracing (red), at "Systole" panel.)');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Circulatory system', 'In vertebrates, the circulatory system is a system of organs that includes the heart, blood vessels, and blood which is circulated throughout the body. It includes the cardiovascular system, or vascular system, that consists of the heart and blood vessels (from Greek kardia meaning heart, and Latin vascula meaning vessels). The circulatory system has two divisions, a systemic circulation or circuit, and a pulmonary circulation or circuit. Some sources use the terms cardiovascular system and vascular system interchangeably with circulatory system. The network of blood vessels are the great vessels of the heart including large elastic arteries, and large veins; other arteries, smaller arterioles, capillaries that join with venules (small veins), and other veins. The circulatory system is closed in vertebrates, which means that the blood never leaves the network of blood vessels. Many invertebrates such as arthropods have an open circulatory system with a heart that pumps a hemolymph which returns via the body cavity rather than via blood vessels. Diploblasts such as sponges and comb jellies lack a circulatory system.', 'Wikipedia: Circulatory system', 'https://en.wikipedia.org/w/index.php?title=Circulatory_system&oldid=1373809131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'In vertebrates, the circulatory system is a system of organs that includes the heart, blood vessels, and blood which is circulated throughout the body. It includes the cardiovascular system, or vascular system, that consists of the heart and blood vessels (from Greek kardia meaning heart, and Latin vascula meaning vessels). The circulatory system has two divisions, a systemic circulation or circuit, and a pulmonary circulation or circuit. Some sources use the terms cardiovascular system and vascular system interchangeably with circulatory system. The network of blood vessels are the great vessels of the heart including large elastic arteries, and large veins; other arteries, smaller arterioles, capillaries that join with venules (small veins), and other veins. The circulatory system is closed in vertebrates, which means that the blood never leaves the network of blood vessels. Many invertebrates such as arthropods have an open circulatory system with a heart that pumps a hemolymph which returns via the body cavity rather than via blood vessels. Diploblasts such as sponges and comb jellies lack a circulatory system.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Circulatory system', 'Blood is a fluid consisting of plasma, red blood cells, white blood cells, and platelets; it is circulated around the body carrying oxygen and nutrients to the tissues and collecting and disposing of waste materials. Circulated nutrients include proteins and minerals and other components include hemoglobin, hormones, and gases such as oxygen and carbon dioxide. These substances provide nourishment, help the immune system to fight diseases, and help maintain homeostasis by stabilizing temperature and natural pH. In vertebrates, the lymphatic system is complementary to the circulatory system. The lymphatic system carries excess plasma (filtered from the circulatory system capillaries as interstitial fluid between cells) away from the body tissues via accessory routes that return excess fluid back to blood circulation as lymph. The lymphatic system is a subsystem that is essential for the functioning of the blood circulatory system; without it the blood would become depleted of fluid. The lymphatic system also works with the immune system. The circulation of lymph takes much longer than that of blood and, unlike the closed (blood) circulatory system, the lymphatic system is an open system. Some sources describe it as a secondary circulatory system.', 'Wikipedia: Circulatory system', 'https://en.wikipedia.org/w/index.php?title=Circulatory_system&oldid=1373809131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Blood is a fluid consisting of plasma, red blood cells, white blood cells, and platelets; it is circulated around the body carrying oxygen and nutrients to the tissues and collecting and disposing of waste materials. Circulated nutrients include proteins and minerals and other components include hemoglobin, hormones, and gases such as oxygen and carbon dioxide. These substances provide nourishment, help the immune system to fight diseases, and help maintain homeostasis by stabilizing temperature and natural pH. In vertebrates, the lymphatic system is complementary to the circulatory system. The lymphatic system carries excess plasma (filtered from the circulatory system capillaries as interstitial fluid between cells) away from the body tissues via accessory routes that return excess fluid back to blood circulation as lymph. The lymphatic system is a subsystem that is essential for the functioning of the blood circulatory system; without it the blood would become depleted of fluid. The lymphatic system also works with the immune system. The circulation of lymph takes much longer than that of blood and, unlike the closed (blood) circulatory system, the lymphatic system is an open system. Some sources describe it as a secondary circulatory system.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Circulatory system', 'The circulatory system can be affected by many cardiovascular diseases. Cardiologists are medical professionals who specialise in the heart, and cardiothoracic surgeons specialise in operating on the heart and its surrounding areas. Vascular surgeons focus on disorders of the blood vessels, and lymphatic vessels.', 'Wikipedia: Circulatory system', 'https://en.wikipedia.org/w/index.php?title=Circulatory_system&oldid=1373809131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The circulatory system can be affected by many cardiovascular diseases. Cardiologists are medical professionals who specialise in the heart, and cardiothoracic surgeons specialise in operating on the heart and its surrounding areas. Vascular surgeons focus on disorders of the blood vessels, and lymphatic vessels.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Circulatory system: Structure', 'The circulatory system includes the heart, blood vessels, and blood. The cardiovascular system in all vertebrates consists of the heart and blood vessels. Some sources use the terms cardiovascular system and vascular system interchangeably with circulatory system. The circulatory system is further divided into two major circuits – a pulmonary circulation, and a systemic circulation. The pulmonary circulation is a circuit loop from the right heart taking deoxygenated blood to the lungs where it is oxygenated and returned to the left heart. The systemic circulation is a circuit loop that delivers oxygenated blood from the left heart to the rest of the body, and returns deoxygenated blood back to the right heart via large veins known as the venae cavae. The systemic circulation can also be defined as two parts – a macrocirculation and a microcirculation. An average adult contains five to six quarts (roughly 4.7 to 5.7 liters) of blood, accounting for approximately 7% of their total body weight. Blood consists of plasma, red blood cells, white blood cells, and platelets. The digestive system also works with the circulatory system to provide the nutrients the system needs to keep the heart pumping.', 'Wikipedia: Circulatory system', 'https://en.wikipedia.org/w/index.php?title=Circulatory_system&oldid=1373809131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The circulatory system includes the heart, blood vessels, and blood. The cardiovascular system in all vertebrates consists of the heart and blood vessels. Some sources use the terms cardiovascular system and vascular system interchangeably with circulatory system. The circulatory system is further divided into two major circuits – a pulmonary circulation, and a systemic circulation. The pulmonary circulation is a circuit loop from the right heart taking deoxygenated blood to the lungs where it is oxygenated and returned to the left heart. The systemic circulation is a circuit loop that delivers oxygenated blood from the left heart to the rest of the body, and returns deoxygenated blood back to the right heart via large veins known as the venae cavae. The systemic circulation can also be defined as two parts – a macrocirculation and a microcirculation. An average adult contains five to six quarts (roughly 4.7 to 5.7 liters) of blood, accounting for approximately 7% of their total body weight. Blood consists of plasma, red blood cells, white blood cells, and platelets. The digestive system also works with the circulatory system to provide the nutrients the system needs to keep the heart pumping.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Circulatory system: Structure', 'Further circulatory routes are associated, such as the coronary circulation to the heart itself, the cerebral circulation to the brain, renal circulation to the kidneys, and bronchial circulation to the bronchi in the lungs. The human circulatory system is closed, meaning that the blood is contained within the vascular network. Nutrients travel through tiny blood vessels of the microcirculation to reach organs. The lymphatic system is an essential subsystem of the circulatory system consisting of a network of lymphatic vessels, lymph nodes, organs, tissues and circulating lymph. This subsystem is an open system. A major function is to carry the lymph, draining and returning interstitial fluid into the lymphatic ducts back to the heart for return to the circulatory system. Another major function is working together with the immune system to provide defense against pathogens.', 'Wikipedia: Circulatory system', 'https://en.wikipedia.org/w/index.php?title=Circulatory_system&oldid=1373809131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Further circulatory routes are associated, such as the coronary circulation to the heart itself, the cerebral circulation to the brain, renal circulation to the kidneys, and bronchial circulation to the bronchi in the lungs. The human circulatory system is closed, meaning that the blood is contained within the vascular network. Nutrients travel through tiny blood vessels of the microcirculation to reach organs. The lymphatic system is an essential subsystem of the circulatory system consisting of a network of lymphatic vessels, lymph nodes, organs, tissues and circulating lymph. This subsystem is an open system. A major function is to carry the lymph, draining and returning interstitial fluid into the lymphatic ducts back to the heart for return to the circulatory system. Another major function is working together with the immune system to provide defense against pathogens.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Circulatory system: Heart', 'The heart pumps blood to all parts of the body. In the human heart there is one atrium and one ventricle for each circulation, and with both a systemic and a pulmonary circulation there are four chambers in total: left atrium, left ventricle, right atrium and right ventricle.', 'Wikipedia: Circulatory system', 'https://en.wikipedia.org/w/index.php?title=Circulatory_system&oldid=1373809131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The heart pumps blood to all parts of the body. In the human heart there is one atrium and one ventricle for each circulation, and with both a systemic and a pulmonary circulation there are four chambers in total: left atrium, left ventricle, right atrium and right ventricle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Circulatory system: Pulmonary circulation', 'Oxygen-deprived blood from the superior and inferior vena cava enters the right atrium of the heart and flows through the tricuspid valve (right atrioventricular valve) into the right ventricle, from which it is then pumped through the pulmonary semilunar valve into the pulmonary artery to the lungs. Gas exchange occurs in the lungs, whereby CO2 is released from the blood, and oxygen is absorbed. The pulmonary vein returns the now oxygen-rich blood to the left atrium. A separate circuit from the systemic circulation, the bronchial circulation supplies blood to the tissue of the larger airways of the lung.', 'Wikipedia: Circulatory system', 'https://en.wikipedia.org/w/index.php?title=Circulatory_system&oldid=1373809131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Oxygen-deprived blood from the superior and inferior vena cava enters the right atrium of the heart and flows through the tricuspid valve (right atrioventricular valve) into the right ventricle, from which it is then pumped through the pulmonary semilunar valve into the pulmonary artery to the lungs. Gas exchange occurs in the lungs, whereby CO2 is released from the blood, and oxygen is absorbed. The pulmonary vein returns the now oxygen-rich blood to the left atrium. A separate circuit from the systemic circulation, the bronchial circulation supplies blood to the tissue of the larger airways of the lung.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Circulatory system: Systemic circulation', 'The systemic circulation is a circuit loop that delivers oxygenated blood from the left heart to the rest of the body through the aorta. Deoxygenated blood is returned in the systemic circulation to the right heart via two large veins, the inferior vena cava and superior vena cava, where it is pumped from the right atrium into the pulmonary circulation for oxygenation. The systemic circulation can also be defined as having two parts – a macrocirculation and a microcirculation.', 'Wikipedia: Circulatory system', 'https://en.wikipedia.org/w/index.php?title=Circulatory_system&oldid=1373809131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The systemic circulation is a circuit loop that delivers oxygenated blood from the left heart to the rest of the body through the aorta. Deoxygenated blood is returned in the systemic circulation to the right heart via two large veins, the inferior vena cava and superior vena cava, where it is pumped from the right atrium into the pulmonary circulation for oxygenation. The systemic circulation can also be defined as having two parts – a macrocirculation and a microcirculation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac conduction system', 'The cardiac conduction system (CCS, also called the electrical conduction system of the heart) transmits the signals generated by the sinoatrial node – the heart''s pacemaker – to cause the heart muscle to contract, and pump blood through the body''s circulatory system. The pacemaking signal travels through the right atrium to the atrioventricular node, along the bundle of His, and through the bundle branches to Purkinje fibers in the walls of the ventricles. The Purkinje fibers transmit the signals more rapidly to stimulate contraction of the ventricles. The conduction system consists of specialized heart muscle cells, situated within the myocardium. There is a skeleton of fibrous tissue that surrounds the conduction system which can be seen on an ECG. Dysfunction of the conduction system can cause irregular heart rhythms including rhythms that are too fast or too slow.', 'Wikipedia: Cardiac conduction system', 'https://en.wikipedia.org/w/index.php?title=Cardiac_conduction_system&oldid=1366590372', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'The cardiac conduction system (CCS, also called the electrical conduction system of the heart) transmits the signals generated by the sinoatrial node – the heart''s pacemaker – to cause the heart muscle to contract, and pump blood through the body''s circulatory system. The pacemaking signal travels through the right atrium to the atrioventricular node, along the bundle of His, and through the bundle branches to Purkinje fibers in the walls of the ventricles. The Purkinje fibers transmit the signals more rapidly to stimulate contraction of the ventricles. The conduction system consists of specialized heart muscle cells, situated within the myocardium. There is a skeleton of fibrous tissue that surrounds the conduction system which can be seen on an ECG. Dysfunction of the conduction system can cause irregular heart rhythms including rhythms that are too fast or too slow.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac conduction system: Structure', 'Electrical signals arising in the SA node (located in the right atrium) stimulate the atria to contract. Then the signals travel to the atrioventricular node (AV node), which is located in the interatrial septum. After a short delay that gives the ventricles time to fill with blood, the electrical signal diverges and is conducted through the left and right bundle branches of His to the respective Purkinje fibers for each side of the heart, as well as to the endocardium at the apex of the heart, then finally to the ventricular epicardium; causing the ventricles to contract. These signals are generated rhythmically, which results in the coordinated rhythmic contraction and relaxation of the heart. On the microscopic level, the wave of depolarization propagates to adjacent cells via gap junctions located on the intercalated disc. The heart is a functional syncytium as opposed to a skeletal muscle syncytium. In a functional syncytium, electrical impulses propagate freely between cells in every direction, so that the myocardium functions as a single contractile unit. This property allows rapid, synchronous depolarization of the myocardium. While advantageous under normal circumstances, this property can be detrimental, as it has potential to allow the propagation of incorrect electrical signals. These gap junctions can close to isolate damaged or dying tissue, as in a myocardial infarction (heart attack).', 'Wikipedia: Cardiac conduction system', 'https://en.wikipedia.org/w/index.php?title=Cardiac_conduction_system&oldid=1366590372', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Electrical signals arising in the SA node (located in the right atrium) stimulate the atria to contract. Then the signals travel to the atrioventricular node (AV node), which is located in the interatrial septum. After a short delay that gives the ventricles time to fill with blood, the electrical signal diverges and is conducted through the left and right bundle branches of His to the respective Purkinje fibers for each side of the heart, as well as to the endocardium at the apex of the heart, then finally to the ventricular epicardium; causing the ventricles to contract. These signals are generated rhythmically, which results in the coordinated rhythmic contraction and relaxation of the heart. On the microscopic level, the wave of depolarization propagates to adjacent cells via gap junctions located on the intercalated disc. The heart is a functional syncytium as opposed to a skeletal muscle syncytium. In a functional syncytium, electrical impulses propagate freely between cells in every direction, so that the myocardium functions as a single contractile unit. This property allows rapid, synchronous depolarization of the myocardium. While advantageous under normal circumstances, this property can be detrimental, as it has potential to allow the propagation of incorrect electrical signals. These gap junctions can close to isolate damaged or dying tissue, as in a myocardial infarction (heart attack).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac conduction system: Development', 'Embryologic evidence of generation of the cardiac conduction system illuminates the respective roles of this specialized set of cells. Innervation of the heart begins with a brain only centered parasympathetic cholinergic first order. It is then followed by rapid growth of a second order sympathetic adrenergic system arising from the formation of the thoracic spinal ganglia. The third order of electrical influence of the heart is derived from the vagus nerve as the other peripheral organs form.', 'Wikipedia: Cardiac conduction system', 'https://en.wikipedia.org/w/index.php?title=Cardiac_conduction_system&oldid=1366590372', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Embryologic evidence of generation of the cardiac conduction system illuminates the respective roles of this specialized set of cells. Innervation of the heart begins with a brain only centered parasympathetic cholinergic first order. It is then followed by rapid growth of a second order sympathetic adrenergic system arising from the formation of the thoracic spinal ganglia. The third order of electrical influence of the heart is derived from the vagus nerve as the other peripheral organs form.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac conduction system: Action potential generation', 'Cardiac muscle has some similarities to neurons and skeletal muscle, as well as important unique properties. Like a neuron, a given myocardial cell has a negative membrane potential when at rest. Stimulation above a threshold value induces the opening of voltage-gated ion channels and a flood of cations into the cell. The positively charged ions entering the cell cause the depolarization characteristic of an action potential. Like skeletal muscle, depolarization causes the opening of voltage-gated calcium channels and release of Ca2+ from the t-tubules. This influx of calcium causes calcium-induced calcium release from the sarcoplasmic reticulum, and free Ca2+ causes muscle contraction. After a delay, potassium channels reopen, and the resulting flow of K+ out of the cell causes repolarization to the resting state. There are important physiological differences between nodal cells and ventricular cells; the specific differences in ion channels and mechanisms of polarization give rise to unique properties of SA node cells, most importantly the spontaneous depolarizations necessary for the SA node''s pacemaker activity.', 'Wikipedia: Cardiac conduction system', 'https://en.wikipedia.org/w/index.php?title=Cardiac_conduction_system&oldid=1366590372', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Cardiac muscle has some similarities to neurons and skeletal muscle, as well as important unique properties. Like a neuron, a given myocardial cell has a negative membrane potential when at rest. Stimulation above a threshold value induces the opening of voltage-gated ion channels and a flood of cations into the cell. The positively charged ions entering the cell cause the depolarization characteristic of an action potential. Like skeletal muscle, depolarization causes the opening of voltage-gated calcium channels and release of Ca2+ from the t-tubules. This influx of calcium causes calcium-induced calcium release from the sarcoplasmic reticulum, and free Ca2+ causes muscle contraction. After a delay, potassium channels reopen, and the resulting flow of K+ out of the cell causes repolarization to the resting state. There are important physiological differences between nodal cells and ventricular cells; the specific differences in ion channels and mechanisms of polarization give rise to unique properties of SA node cells, most importantly the spontaneous depolarizations necessary for the SA node''s pacemaker activity.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac conduction system: Requirements for effective pumping', 'In order to maximize efficiency of contractions and cardiac output, the conduction system of the heart has: Substantial atrial to ventricular delay. This will allow the atria to completely empty their contents into the ventricles; simultaneous contraction would cause inefficient filling and backflow. The atria are electrically isolated from the ventricles, connected only via the AV node which briefly delays the signal. Coordinated contraction of ventricular cells. The ventricles must maximize systolic pressure to force blood through the circulation, so all the ventricular cells must work together. Ventricular contraction begins at the apex of the heart, progressing upwards to eject blood into the great arteries. Contraction that squeezes blood towards the exit is more efficient than a simple squeeze from all directions. Although the ventricular stimulus originates from the AV node in the wall separating the atria and ventricles, the Bundle of His conducts the signal to the apex. Depolarization propagates through cardiac muscle very rapidly. Cells of the ventricles contract nearly simultaneously. The action potentials of cardiac muscle are unusually sustained. This prevents premature relaxation, maintaining initial contraction until the entire myocardium has had time to depolarize and contract.', 'Wikipedia: Cardiac conduction system', 'https://en.wikipedia.org/w/index.php?title=Cardiac_conduction_system&oldid=1366590372', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'In order to maximize efficiency of contractions and cardiac output, the conduction system of the heart has: Substantial atrial to ventricular delay. This will allow the atria to completely empty their contents into the ventricles; simultaneous contraction would cause inefficient filling and backflow. The atria are electrically isolated from the ventricles, connected only via the AV node which briefly delays the signal. Coordinated contraction of ventricular cells. The ventricles must maximize systolic pressure to force blood through the circulation, so all the ventricular cells must work together. Ventricular contraction begins at the apex of the heart, progressing upwards to eject blood into the great arteries. Contraction that squeezes blood towards the exit is more efficient than a simple squeeze from all directions. Although the ventricular stimulus originates from the AV node in the wall separating the atria and ventricles, the Bundle of His conducts the signal to the apex. Depolarization propagates through cardiac muscle very rapidly. Cells of the ventricles contract nearly simultaneously. The action potentials of cardiac muscle are unusually sustained. This prevents premature relaxation, maintaining initial contraction until the entire myocardium has had time to depolarize and contract.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac conduction system: Requirements for effective pumping', 'Absence of tetany. After contracting, the heart must relax to fill up again. Sustained contraction of the heart without relaxation would be fatal, and this is prevented by a temporary inactivation of certain ion channels.', 'Wikipedia: Cardiac conduction system', 'https://en.wikipedia.org/w/index.php?title=Cardiac_conduction_system&oldid=1366590372', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Absence of tetany. After contracting, the heart must relax to fill up again. Sustained contraction of the heart without relaxation would be fatal, and this is prevented by a temporary inactivation of certain ion channels.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac conduction system: Electrical activity', 'An electrocardiogram is a recording of the electrical activity of the heart.', 'Wikipedia: Cardiac conduction system', 'https://en.wikipedia.org/w/index.php?title=Cardiac_conduction_system&oldid=1366590372', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'An electrocardiogram is a recording of the electrical activity of the heart.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Cardiac conduction system: SA node: P wave', 'Under normal conditions, electrical activity is spontaneously generated by the SA node, the cardiac pacemaker. This electrical impulse is propagated throughout the right atrium, and through Bachmann''s bundle to the left atrium, stimulating the myocardium of the atria to contract. The conduction of the electrical impulses throughout the atria is seen on the ECG as the P wave. As the electrical activity is spreading throughout the atria, it travels via specialized pathways, known as internodal tracts, from the SA node to the AV node.', 'Wikipedia: Cardiac conduction system', 'https://en.wikipedia.org/w/index.php?title=Cardiac_conduction_system&oldid=1366590372', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Under normal conditions, electrical activity is spontaneously generated by the SA node, the cardiac pacemaker. This electrical impulse is propagated throughout the right atrium, and through Bachmann''s bundle to the left atrium, stimulating the myocardium of the atria to contract. The conduction of the electrical impulses throughout the atria is seen on the ECG as the P wave. As the electrical activity is spreading throughout the atria, it travels via specialized pathways, known as internodal tracts, from the SA node to the AV node.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood pressure', 'Blood pressure (BP) is the pressure of circulating blood against the walls of blood vessels. Most of this pressure results from the heart pumping blood through the circulatory system. When used without qualification, the term "blood pressure" refers to the pressure in a brachial artery, where it is most commonly measured. Blood pressure is usually expressed in terms of the systolic pressure (maximum pressure during one heartbeat) over diastolic pressure (minimum pressure between heartbeats) in the cardiac cycle. It is measured in millimetres of mercury (mmHg) above the surrounding atmospheric pressure, or in kilopascals (kPa). The difference between the systolic and diastolic pressures is known as pulse pressure, while the average pressure during a cardiac cycle is known as mean arterial pressure. Blood pressure is one of the vital signs—together with respiratory rate, heart rate, oxygen saturation, and body temperature—that healthcare professionals use in evaluating a patient''s health. Normal resting blood pressure in an adult is under 120/80 mmHg according to the AHA and ACC, and under 120/70 mmHg according to the ESC, and over 90/60 mmHg, though low blood pressure is usually not harmful unless it causes symptoms. Globally, the average blood pressure, age-standardized, has remained about the same since 1975 at approximately 127/79 mmHg in men and 122/77 mmHg in women, although these averages mask significant regional differences.', 'Wikipedia: Blood pressure', 'https://en.wikipedia.org/w/index.php?title=Blood_pressure&oldid=1379381701', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Blood pressure (BP) is the pressure of circulating blood against the walls of blood vessels. Most of this pressure results from the heart pumping blood through the circulatory system. When used without qualification, the term "blood pressure" refers to the pressure in a brachial artery, where it is most commonly measured. Blood pressure is usually expressed in terms of the systolic pressure (maximum pressure during one heartbeat) over diastolic pressure (minimum pressure between heartbeats) in the cardiac cycle. It is measured in millimetres of mercury (mmHg) above the surrounding atmospheric pressure, or in kilopascals (kPa). The difference between the systolic and diastolic pressures is known as pulse pressure, while the average pressure during a cardiac cycle is known as mean arterial pressure. Blood pressure is one of the vital signs—together with respiratory rate, heart rate, oxygen saturation, and body temperature—that healthcare professionals use in evaluating a patient''s health. Normal resting blood pressure in an adult is under 120/80 mmHg according to the AHA and ACC, and under 120/70 mmHg according to the ESC, and over 90/60 mmHg, though low blood pressure is usually not harmful unless it causes symptoms. Globally, the average blood pressure, age-standardized, has remained about the same since 1975 at approximately 127/79 mmHg in men and 122/77 mmHg in women, although these averages mask significant regional differences.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood pressure', 'Blood pressure is influenced by cardiac output, systemic vascular resistance, blood volume, and arterial stiffness. It varies depending on a person''s situation, emotional state, activity level, and overall health. In the short term, blood pressure is regulated by baroreceptors, which act via the brain to influence the nervous system and endocrine system. Blood pressure that is too low is called hypotension, pressure that is consistently too high is called hypertension, and normal pressure is called normotension. Both hypertension and hypotension have many causes and may occur suddenly or develop over time. Long-term hypertension is a risk factor for many diseases, including stroke, heart disease, and kidney failure.', 'Wikipedia: Blood pressure', 'https://en.wikipedia.org/w/index.php?title=Blood_pressure&oldid=1379381701', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Blood pressure is influenced by cardiac output, systemic vascular resistance, blood volume, and arterial stiffness. It varies depending on a person''s situation, emotional state, activity level, and overall health. In the short term, blood pressure is regulated by baroreceptors, which act via the brain to influence the nervous system and endocrine system. Blood pressure that is too low is called hypotension, pressure that is consistently too high is called hypertension, and normal pressure is called normotension. Both hypertension and hypotension have many causes and may occur suddenly or develop over time. Long-term hypertension is a risk factor for many diseases, including stroke, heart disease, and kidney failure.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood pressure: Systemic arterial pressure', 'Blood pressure measurements can be influenced by circumstances of measurement. Guidelines use different thresholds for office (also known as clinic), home (when the person measures their own blood pressure at home), and ambulatory blood pressure (using an automated device over a 24-hour period). The risk of cardiovascular disease increases progressively above a systolic blood pressure of 90 mmHg. Observational studies demonstrate that people who maintain arterial pressures at the low end of these pressure ranges have much better long-term cardiovascular health. There is an ongoing medical debate over what is the optimal level of blood pressure to target when using drugs to lower blood pressure with hypertension, particularly in older adults.', 'Wikipedia: Blood pressure', 'https://en.wikipedia.org/w/index.php?title=Blood_pressure&oldid=1379381701', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Blood pressure measurements can be influenced by circumstances of measurement. Guidelines use different thresholds for office (also known as clinic), home (when the person measures their own blood pressure at home), and ambulatory blood pressure (using an automated device over a 24-hour period). The risk of cardiovascular disease increases progressively above a systolic blood pressure of 90 mmHg. Observational studies demonstrate that people who maintain arterial pressures at the low end of these pressure ranges have much better long-term cardiovascular health. There is an ongoing medical debate over what is the optimal level of blood pressure to target when using drugs to lower blood pressure with hypertension, particularly in older adults.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood pressure: Systemic arterial pressure', 'Blood pressure fluctuates from minute to minute and normally shows a circadian rhythm over a 24-hour period, with highest readings in the early morning and evenings and lowest readings at night. Loss of the normal fall in blood pressure at night is associated with a greater future risk of cardiovascular disease and there is evidence that night-time blood pressure is a stronger predictor of cardiovascular events than day-time blood pressure. Blood pressure varies over longer time periods (months to years) and this variability predicts adverse outcomes. Blood pressure also changes in response to temperature, noise, emotional stress, consumption of food or liquid, dietary factors, physical activity, changes in posture (such as standing-up), drugs, and disease. The variability in blood pressure and the better predictive value of ambulatory blood pressure measurements has led some authorities, such as the National Institute for Health and Care Excellence (NICE) in the UK, to advocate for the use of ambulatory blood pressure as the preferred method for diagnosis of hypertension. Various other factors, such as age and sex, also influence a person''s blood pressure. Differences between left-arm and right-arm blood pressure measurements tend to be small. However, occasionally there is a consistent difference greater than 10 mmHg which may need further investigation, e.g. for peripheral arterial disease, obstructive arterial disease or aortic dissection.', 'Wikipedia: Blood pressure', 'https://en.wikipedia.org/w/index.php?title=Blood_pressure&oldid=1379381701', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Blood pressure fluctuates from minute to minute and normally shows a circadian rhythm over a 24-hour period, with highest readings in the early morning and evenings and lowest readings at night. Loss of the normal fall in blood pressure at night is associated with a greater future risk of cardiovascular disease and there is evidence that night-time blood pressure is a stronger predictor of cardiovascular events than day-time blood pressure. Blood pressure varies over longer time periods (months to years) and this variability predicts adverse outcomes. Blood pressure also changes in response to temperature, noise, emotional stress, consumption of food or liquid, dietary factors, physical activity, changes in posture (such as standing-up), drugs, and disease. The variability in blood pressure and the better predictive value of ambulatory blood pressure measurements has led some authorities, such as the National Institute for Health and Care Excellence (NICE) in the UK, to advocate for the use of ambulatory blood pressure as the preferred method for diagnosis of hypertension. Various other factors, such as age and sex, also influence a person''s blood pressure. Differences between left-arm and right-arm blood pressure measurements tend to be small. However, occasionally there is a consistent difference greater than 10 mmHg which may need further investigation, e.g. for peripheral arterial disease, obstructive arterial disease or aortic dissection.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood pressure: Systemic arterial pressure', 'There is no accepted diagnostic standard for hypotension, although pressures less than 90/60 are commonly regarded as hypotensive. In practice blood pressure is considered too low only if symptoms are present.', 'Wikipedia: Blood pressure', 'https://en.wikipedia.org/w/index.php?title=Blood_pressure&oldid=1379381701', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'There is no accepted diagnostic standard for hypotension, although pressures less than 90/60 are commonly regarded as hypotensive. In practice blood pressure is considered too low only if symptoms are present.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood pressure: Fetal blood pressure', 'In pregnancy, it is the fetal heart and not the mother''s heart that builds up the fetal blood pressure to drive blood through the fetal circulation. The blood pressure in the fetal aorta is approximately 30 mmHg at 20 weeks of gestation, and increases to approximately 45 mmHg at 40 weeks of gestation.', 'Wikipedia: Blood pressure', 'https://en.wikipedia.org/w/index.php?title=Blood_pressure&oldid=1379381701', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
