insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood pressure: Childhood', 'In children the normal ranges for blood pressure are lower than for adults and depend on height. Reference blood pressure values have been developed for children in different countries, based on the distribution of blood pressure in children of these countries.', 'Wikipedia: Blood pressure', 'https://en.wikipedia.org/w/index.php?title=Blood_pressure&oldid=1379381701', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'In children the normal ranges for blood pressure are lower than for adults and depend on height. Reference blood pressure values have been developed for children in different countries, based on the distribution of blood pressure in children of these countries.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood pressure: Aging adults', 'In adults in most societies, systolic blood pressure tends to rise from early adulthood onward, up to at least age 70; diastolic pressure tends to begin to rise at the same time but start to fall earlier in mid-life, approximately age 55. Mean blood pressure rises from early adulthood, plateauing in mid-life, while pulse pressure rises quite markedly after the age of 40. Consequently, in many older people, systolic blood pressure often exceeds the normal adult range, if the diastolic pressure is in the normal range this is termed isolated systolic hypertension. The rise in pulse pressure with age is attributed to increased stiffness of the arteries. An age-related rise in blood pressure is not considered healthy and is not observed in some isolated unacculturated communities.', 'Wikipedia: Blood pressure', 'https://en.wikipedia.org/w/index.php?title=Blood_pressure&oldid=1379381701', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'In adults in most societies, systolic blood pressure tends to rise from early adulthood onward, up to at least age 70; diastolic pressure tends to begin to rise at the same time but start to fall earlier in mid-life, approximately age 55. Mean blood pressure rises from early adulthood, plateauing in mid-life, while pulse pressure rises quite markedly after the age of 40. Consequently, in many older people, systolic blood pressure often exceeds the normal adult range, if the diastolic pressure is in the normal range this is termed isolated systolic hypertension. The rise in pulse pressure with age is attributed to increased stiffness of the arteries. An age-related rise in blood pressure is not considered healthy and is not observed in some isolated unacculturated communities.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood', 'Blood is a specialized form of connective tissue and body fluid in the circulatory system of humans and other vertebrates that delivers necessary substances such as nutrients and oxygen to the cells of the body, and transports metabolic waste products away from those same cells. Blood is composed of blood cells suspended in plasma. Plasma, which constitutes 55% of blood fluid, is mostly water (92% by volume), and contains proteins, glucose, mineral ions, and hormones. The blood cells are mainly red blood cells (erythrocytes), white blood cells (leukocytes), and (in mammals) platelets (thrombocytes). The most abundant cells are red blood cells. These contain hemoglobin, which facilitates oxygen transport by reversibly binding to it, increasing its solubility. Jawed vertebrates have an adaptive immune system, based largely on white blood cells. White blood cells help to resist infections and parasites. Platelets are important in the clotting of blood. Blood is circulated around the body through blood vessels by the pumping action of the heart. In animals with lungs, arterial blood carries oxygen from inhaled air to the tissues of the body, and venous blood carries carbon dioxide, a waste product of metabolism produced by cells, from the tissues to the lungs to be exhaled. Blood is bright red when its hemoglobin is oxygenated and dark red when it is deoxygenated.', 'Wikipedia: Blood', 'https://en.wikipedia.org/w/index.php?title=Blood&oldid=1379335873', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Blood is a specialized form of connective tissue and body fluid in the circulatory system of humans and other vertebrates that delivers necessary substances such as nutrients and oxygen to the cells of the body, and transports metabolic waste products away from those same cells. Blood is composed of blood cells suspended in plasma. Plasma, which constitutes 55% of blood fluid, is mostly water (92% by volume), and contains proteins, glucose, mineral ions, and hormones. The blood cells are mainly red blood cells (erythrocytes), white blood cells (leukocytes), and (in mammals) platelets (thrombocytes). The most abundant cells are red blood cells. These contain hemoglobin, which facilitates oxygen transport by reversibly binding to it, increasing its solubility. Jawed vertebrates have an adaptive immune system, based largely on white blood cells. White blood cells help to resist infections and parasites. Platelets are important in the clotting of blood. Blood is circulated around the body through blood vessels by the pumping action of the heart. In animals with lungs, arterial blood carries oxygen from inhaled air to the tissues of the body, and venous blood carries carbon dioxide, a waste product of metabolism produced by cells, from the tissues to the lungs to be exhaled. Blood is bright red when its hemoglobin is oxygenated and dark red when it is deoxygenated.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood', 'Medical terms related to blood often begin with hemo-, hemato-, haemo- or haemato- from the Greek word αἷμα (haima) for "blood". In terms of anatomy and histology, blood is considered a specialized form of connective tissue, given its composition of cells and cell fragments suspended in plasma.', 'Wikipedia: Blood', 'https://en.wikipedia.org/w/index.php?title=Blood&oldid=1379335873', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Medical terms related to blood often begin with hemo-, hemato-, haemo- or haemato- from the Greek word αἷμα (haima) for "blood". In terms of anatomy and histology, blood is considered a specialized form of connective tissue, given its composition of cells and cell fragments suspended in plasma.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood: Functions', 'Supply of oxygen to tissues (bound to hemoglobin, which is carried in red cells) Supply of nutrients such as glucose, amino acids, and fatty acids (dissolved in the blood or bound to plasma proteins (e.g., blood lipids)) Immunological functions, including circulation of white blood cells, and detection of foreign material by antibodies Coagulation, the response to a broken blood vessel, the conversion of blood from a liquid to a semisolid gel to stop bleeding Messenger functions, including the transport of hormones and the signaling of tissue damage', 'Wikipedia: Blood', 'https://en.wikipedia.org/w/index.php?title=Blood&oldid=1379335873', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Supply of oxygen to tissues (bound to hemoglobin, which is carried in red cells) Supply of nutrients such as glucose, amino acids, and fatty acids (dissolved in the blood or bound to plasma proteins (e.g., blood lipids)) Immunological functions, including circulation of white blood cells, and detection of foreign material by antibodies Coagulation, the response to a broken blood vessel, the conversion of blood from a liquid to a semisolid gel to stop bleeding Messenger functions, including the transport of hormones and the signaling of tissue damage');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood: In mammals', 'Blood accounts for 7% of the human body weight, with an average density around 1060 kg/m3, very close to pure water''s density of 1000 kg/m3. The average adult has a blood volume of roughly 5 litres (11 US pt) or 1.3 gallons, which is composed of plasma and formed elements. The formed elements are the two types of blood cell or corpuscle – the red blood cells, (erythrocytes) and white blood cells (leukocytes) – and the cell fragments called platelets that are involved in clotting. By volume, the red blood cells constitute about 45% of whole blood, the plasma about 54.3%, and white cells about 0.7%.', 'Wikipedia: Blood', 'https://en.wikipedia.org/w/index.php?title=Blood&oldid=1379335873', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Blood accounts for 7% of the human body weight, with an average density around 1060 kg/m3, very close to pure water''s density of 1000 kg/m3. The average adult has a blood volume of roughly 5 litres (11 US pt) or 1.3 gallons, which is composed of plasma and formed elements. The formed elements are the two types of blood cell or corpuscle – the red blood cells, (erythrocytes) and white blood cells (leukocytes) – and the cell fragments called platelets that are involved in clotting. By volume, the red blood cells constitute about 45% of whole blood, the plasma about 54.3%, and white cells about 0.7%.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood: Cells', '4.7 to 6.1 million (male), 4.2 to 5.4 million (female) erythrocytes: Red blood cells contain the blood''s hemoglobin and distribute oxygen. Mature red blood cells lack a nucleus and organelles in mammals. The red blood cells (together with endothelial vessel cells and other cells) are also marked by glycoproteins that define the different blood types. The proportion of blood occupied by red blood cells is referred to as the hematocrit, and is normally about 45%. The combined surface area of all red blood cells of the human body would be roughly 2,000 times as great as the body''s exterior surface. 4,000–11,000 leukocytes: White blood cells are part of the body''s immune system; they destroy and remove old or aberrant cells and cellular debris, as well as attack infectious agents (pathogens) and foreign substances. The cancer of leukocytes is called leukemia. 200,000–500,000 thrombocytes: Also called platelets, they take part in blood clotting (coagulation). Fibrin from the coagulation cascade creates a mesh over the platelet plug.', 'Wikipedia: Blood', 'https://en.wikipedia.org/w/index.php?title=Blood&oldid=1379335873', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = '4.7 to 6.1 million (male), 4.2 to 5.4 million (female) erythrocytes: Red blood cells contain the blood''s hemoglobin and distribute oxygen. Mature red blood cells lack a nucleus and organelles in mammals. The red blood cells (together with endothelial vessel cells and other cells) are also marked by glycoproteins that define the different blood types. The proportion of blood occupied by red blood cells is referred to as the hematocrit, and is normally about 45%. The combined surface area of all red blood cells of the human body would be roughly 2,000 times as great as the body''s exterior surface. 4,000–11,000 leukocytes: White blood cells are part of the body''s immune system; they destroy and remove old or aberrant cells and cellular debris, as well as attack infectious agents (pathogens) and foreign substances. The cancer of leukocytes is called leukemia. 200,000–500,000 thrombocytes: Also called platelets, they take part in blood clotting (coagulation). Fibrin from the coagulation cascade creates a mesh over the platelet plug.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood: Plasma', 'About 55% of blood is blood plasma, a fluid that is the blood''s liquid medium, which by itself is straw-yellow in color. The total blood plasma volume in an average human is 2.7–3.0 liters (2.8–3.2 quarts). It is essentially an aqueous solution containing 92% water, 8% blood plasma proteins, and trace amounts of other materials. Plasma circulates dissolved nutrients, such as glucose, amino acids, and fatty acids (dissolved in the blood or bound to plasma proteins), and removes waste products, such as carbon dioxide, urea, and lactic acid. The term serum refers to plasma from which the clotting proteins have been removed. Most of the proteins remaining are albumin and immunoglobulins.', 'Wikipedia: Blood', 'https://en.wikipedia.org/w/index.php?title=Blood&oldid=1379335873', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'About 55% of blood is blood plasma, a fluid that is the blood''s liquid medium, which by itself is straw-yellow in color. The total blood plasma volume in an average human is 2.7–3.0 liters (2.8–3.2 quarts). It is essentially an aqueous solution containing 92% water, 8% blood plasma proteins, and trace amounts of other materials. Plasma circulates dissolved nutrients, such as glucose, amino acids, and fatty acids (dissolved in the blood or bound to plasma proteins), and removes waste products, such as carbon dioxide, urea, and lactic acid. The term serum refers to plasma from which the clotting proteins have been removed. Most of the proteins remaining are albumin and immunoglobulins.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood: Acidity', 'Blood pH is regulated to stay within the narrow range of 7.35 to 7.45, making it slightly basic (compensation). Extra-cellular fluid in blood that has a pH below 7.35 is too acidic, whereas blood pH above 7.45 is too basic. A pH below 6.9 or above 7.8 is usually lethal. Blood pH, partial pressure of oxygen (pO2), partial pressure of carbon dioxide (pCO2), and bicarbonate (HCO3−) are carefully regulated by a number of homeostatic mechanisms, which exert their influence principally through the respiratory system and the urinary system to control the acid–base balance and respiration, which is called compensation. An arterial blood gas test measures these. Plasma also circulates hormones transmitting their messages to various tissues. The list of normal reference ranges for various blood electrolytes is extensive.', 'Wikipedia: Blood', 'https://en.wikipedia.org/w/index.php?title=Blood&oldid=1379335873', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'heart' and body = 'Blood pH is regulated to stay within the narrow range of 7.35 to 7.45, making it slightly basic (compensation). Extra-cellular fluid in blood that has a pH below 7.35 is too acidic, whereas blood pH above 7.45 is too basic. A pH below 6.9 or above 7.8 is usually lethal. Blood pH, partial pressure of oxygen (pO2), partial pressure of carbon dioxide (pCO2), and bicarbonate (HCO3−) are carefully regulated by a number of homeostatic mechanisms, which exert their influence principally through the respiratory system and the urinary system to control the acid–base balance and respiration, which is called compensation. An arterial blood gas test measures these. Plasma also circulates hormones transmitting their messages to various tissues. The list of normal reference ranges for various blood electrolytes is extensive.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'heart', 'Blood: In non-mammals', 'Human blood is typical of that of mammals, although the precise details concerning cell numbers, size, protein structure, and so on, vary somewhat between species. In non-mammalian vertebrates, however, there are some key differences: Red blood cells of non-mammalian vertebrates are flattened and ovoid in form, and retain their cell nuclei. There is considerable variation in the types and proportions of white blood cells; for example, acidophils are generally more common than in humans. Platelets are unique to mammals; in other vertebrates, small nucleated, spindle cells called thrombocytes are responsible for blood clotting instead.', 'Wikipedia: Blood', 'https://en.wikipedia.org/w/index.php?title=Blood&oldid=1379335873', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
